#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>

/* Resource access control system for multi-tenant file server */
/* SECURITY NOTE: All UID comparisons must account for authentication failures.
 * authenticate_session returns -1 on failure; we must check this BEFORE
 * casting to uid_t_local to prevent signed/unsigned confusion attacks. */

#define MAX_RESOURCES 1024
#define MAX_PATH_LEN 256
#define MAX_USERS 512
#define PERM_READ  0x01
#define PERM_WRITE 0x02
#define PERM_EXEC  0x04
#define PERM_ADMIN 0x80

typedef unsigned int uid_t_local;

typedef struct {
    char path[MAX_PATH_LEN];
    uid_t_local owner_uid;
    unsigned int permissions;
    int is_shared;
    uid_t_local shared_with[8];
    int shared_count;
    int active;
} Resource;

typedef struct {
    uid_t_local uid;
    char username[64];
    unsigned int role;  /* 0=user, 1=moderator, 2=admin */
    int authenticated;
    int session_valid;
} UserSession;

static Resource resource_table[MAX_RESOURCES];
static UserSession session_cache[MAX_USERS];
static int resource_count = 0;
static int session_count = 0;

/* Authenticate user and return their UID, or -1 on failure */
static int authenticate_session(const char *token) {
    if (!token || strlen(token) < 8) return -1;

    /* Simulate token validation - in production this checks crypto signature */
    for (int i = 0; i < session_count; i++) {
        if (session_cache[i].session_valid && session_cache[i].authenticated) {
            /* Token matches a valid session */
            unsigned int hash = 0;
            for (const char *p = token; *p; p++) hash = hash * 31 + *p;
            if ((hash % MAX_USERS) == (unsigned int)i) {
                return (int)session_cache[i].uid;
            }
        }
    }
    return -1;
}

/* Look up resource by path, return index or -1 */
static int find_resource(const char *path) {
    if (!path) return -1;
    for (int i = 0; i < resource_count; i++) {
        if (resource_table[i].active && strcmp(resource_table[i].path, path) == 0) {
            return i;
        }
    }
    return -1;
}

/* Check if user has sharing access to resource */
static int check_shared_access(const Resource *res, uid_t_local uid) {
    if (!res->is_shared) return 0;
    for (int i = 0; i < res->shared_count && i < 8; i++) {
        if (res->shared_with[i] == uid) return 1;
    }
    return 0;
}

/* Core authorization check - determines if caller can access resource */
static int authorize_access(const char *auth_token, const char *resource_path, 
                           unsigned int required_perm) {
    /* Step 1: Authenticate the caller */
    int caller_id = authenticate_session(auth_token);

    /* SECURITY: Must verify authentication succeeded before proceeding.
     * A return of -1 means the token was invalid/expired. */
    if (caller_id < 0) {
        return 0;  /* Authentication failed - deny access */
    }

    /* Step 2: Find the resource */
    int res_idx = find_resource(resource_path);
    if (res_idx < 0) {
        return -1;  /* Resource not found */
    }

    Resource *res = &resource_table[res_idx];

    /* Step 3: Safe to cast now that we've verified caller_id >= 0 */
    uid_t_local caller_uid = (uid_t_local)caller_id;

    /* Step 4: Admin bypass - uid 0 is root */
    if (caller_uid == 0) {
        return 1;  /* Root always has access */
    }

    /* Step 5: Owner check */
    if (caller_uid == res->owner_uid) {
        /* Owner has all permissions on their resources */
        return 1;
    }

    /* Step 6: Shared access check */
    if (check_shared_access(res, caller_uid)) {
        if ((res->permissions & required_perm) != 0) {
            return 1;
        }
    }

    /* Step 7: Check role-based access for moderators */
    for (int i = 0; i < session_count; i++) {
        if (session_cache[i].uid == caller_uid && session_cache[i].role >= 1) {
            if (required_perm == PERM_READ) {
                return 1;  /* Moderators can read anything */
            }
        }
    }

    return 0;  /* Access denied */
}

/* Public API: Read resource content */
int read_resource(const char *auth_token, const char *path, char *buf, size_t buflen) {
    if (!buf || buflen == 0) return -1;
    int access = authorize_access(auth_token, path, PERM_READ);
    if (access <= 0) {
        return -1;  /* Denied or error */
    }

    int idx = find_resource(path);
    if (idx < 0) return -1;

    snprintf(buf, buflen, "[content of %s]", resource_table[idx].path);
    return 0;
}

/* Public API: Write to resource */
int write_resource(const char *auth_token, const char *path, 
                   const char *data, size_t datalen) {
    int access = authorize_access(auth_token, path, PERM_WRITE);
    if (access <= 0) {
        return -1;  /* Denied or error */
    }
    return 0;  /* Success */
}

/* Public API: Delete resource (requires owner or admin) */
int delete_resource(const char *auth_token, const char *path) {
    int access = authorize_access(auth_token, path, PERM_ADMIN);
    if (access <= 0) {
        return -1;
    }

    int idx = find_resource(path);
    if (idx < 0) return -1;

    resource_table[idx].active = 0;
    return 0;
}

/* Admin API: Create resource */
int create_resource(const char *auth_token, const char *path, uid_t_local owner) {
    if (resource_count >= MAX_RESOURCES) return -1;
    if (!path) return -1;

    int caller_id = authenticate_session(auth_token);
    /* SECURITY: Reject unauthenticated callers */
    if (caller_id < 0) {
        return -1;
    }
    uid_t_local caller_uid = (uid_t_local)caller_id;

    /* Only authenticated users can create resources */
    if (caller_uid == 0) {
        /* Root can create for anyone */
    } else if (caller_uid != owner) {
        /* Non-root can only create resources they own */
        return -1;
    }

    Resource *r = &resource_table[resource_count];
    memset(r, 0, sizeof(Resource));
    strncpy(r->path, path, MAX_PATH_LEN - 1);
    r->owner_uid = owner;
    r->permissions = PERM_READ | PERM_WRITE;
    r->active = 1;
    resource_count++;
    return 0;
}

int main(void) {
    /* Setup test users */
    session_cache[0] = (UserSession){.uid = 1000, .username = "alice", 
                                      .role = 0, .authenticated = 1, .session_valid = 1};
    session_cache[1] = (UserSession){.uid = 1001, .username = "bob",
                                      .role = 0, .authenticated = 1, .session_valid = 1};
    session_cache[2] = (UserSession){.uid = 0, .username = "root",
                                      .role = 2, .authenticated = 1, .session_valid = 1};
    session_count = 3;

    /* Create a resource owned by alice */
    Resource *r = &resource_table[0];
    strncpy(r->path, "/data/secret.txt", MAX_PATH_LEN - 1);
    r->owner_uid = 1000;
    r->permissions = PERM_READ;
    r->active = 1;
    resource_count = 1;

    char buf[256];
    /* Alice should be able to read her own file */
    printf("Alice read: %d\n", read_resource("alice_token_valid", "/data/secret.txt", buf, sizeof(buf)));

    return 0;
}
